function escSub(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}async function load(){const r=await apiFetch('/operacoes/admin/assinaturas');document.getElementById('rows').innerHTML=r.length?r.map(x=>`<tr><td>${escSub(x.cliente_id||'—')}</td><td>${escSub(x.nome_produto||x.produto_id||'—')}</td><td>${escSub(x.frequencia||'—')}</td><td>${x.proxima_cobranca?new Date(x.proxima_cobranca).toLocaleString('pt-PT'):'—'}</td><td>${escSub(x.estado)}</td></tr>`).join(''):'<tr><td colspan="5">Não existem assinaturas reais.</td></tr>'}load().catch(e=>{const el=document.getElementById('rows');el.innerHTML='<tr><td colspan="5"></td></tr>';el.querySelector('td').textContent=e.message||'Erro ao carregar.'});
